"""
scan_config.py — 탐지 설정값 (담당: 김창균)
================================================================
원본 m0609_scan_final.py (scan-final-v17-grouped-settings)의 값을 그대로 옮김.
통합하면서 빠진 값: 로봇 연결·TCP(box_comm이 맞춤), 그리퍼 DO/DI(Modbus로 바뀜),
                   HOME·PLACE_XY(Goal의 poses['home_j'] / poses['measure_zone']로 받음)
================================================================
"""

# 일반 이동 속도 · 가속도
HOME_VEL, HOME_ACC = 60.0, 80.0                  # 관절 deg/s, deg/s²
APPROACH_VEL, APPROACH_ACC = 60.0, 80.0          # 탐색 시작점 관절 이동
LINEAR_VEL, LINEAR_ACC = 80.0, 100.0             # 일반 직선 이동 mm/s (회전 20 deg/s)
TRANSFER_JOINT_VEL, TRANSFER_JOINT_ACC = 60.0, 80.0
GRIP_ROTATE_VEL, GRIP_ROTATE_ACC = 45.0, 90.0    # 집기 각도 회전 deg/s
TILT_VEL, TILT_ACC = 5.0, 10.0                   # 탐색 기울기 회전 deg/s

# 탐색 경로 · 외력 보정 조건 (보정표와 한 세트 — 바꾸면 보정표 다시 측정)
X_LANES = tuple(270.0 + 30.0*i for i in range(11))
Y_START, Y_END = 240.0, -90.0
SCAN_Z = 35.0
SCAN_VEL, SCAN_ACC = 30.0, 40.0
FORCE_LIMIT = 1.5            # 보정 외력 |Fy - 기준| [N]. 1개 샘플 초과 즉시 정지
SAMPLE_PERIOD = 0.05         # 기준 데이터 측정 주기와 동일
BACKWARD_TILT_DEG = 10.0

# 탐색 재개 · 대기
SCAN_RESUME_Y_OFFSET_MM = -50.0   # 접촉 Y에서 BASE Y -50mm 지점부터 다시
RESUME_IGNORE_MM = 15.0           # 재출발 첫 15mm는 접촉 판정 제외
BETWEEN_LINES_WAIT = 0.2
SETTLE_SECONDS = 0.2

# 집기 높이 · 재시도
Z0 = 0.0                     # 탐색 작업대 바닥 TCP Z
MAX_OBJECT_HEIGHT_MM = 80.0
GRIP_DEPTH_FROM_TOP_MM = 15.0   # 집는 높이 = 윗면 - 이 값 (그리퍼 팁 길이, 11/18). 가장 얇은 박스 20mm → 바닥에 안 닿음
                                # (원본: 윗면 높이의 50%. 박스가 겹쳐 있으면 아래 박스까지 걸려서 바꿈)
MIN_GRIP_ABOVE_Z0_MM = 2.0
GRIP_RETRY_ANGLES = (0.0, 45.0, 90.0)    # 원본 실로봇 시험값 (11/17 팀 논의안 0/+30/-30은 보류)
GRIP_RETRY_LIFT_MM = 20.0
PICK_LIFT_MM = 20.0
PICK_HOLD_SECONDS = 0.2
GRIP_FORCE_N = None          # None이면 common.GRIPPER['grip_force_n']
OPEN_WIDTH_MM = None         # None이면 common.GRIPPER['open_width_mm']

# 높이 탐지 실패 반복 (부채꼴 4점 모두 높이 없음)
#   같은 자리(같은 선, Y 차이 30mm 안)에서 이 횟수만큼 실패하면 '스캔공간 막힘'으로 보고 멈춤
#   멈춘 뒤 처리(건너뛰기 등)는 팀 결정 대기 → scan_algorithm.py _on_scan_blocked
HEIGHT_MISS_LIMIT = 3
HEIGHT_MISS_SAME_SPOT_MM = 30.0

# 높이 탐지 지점 · 접촉 조건
PROBE_START_Z = 100.0
PROBE_POINTS = ((25.0, 0.0), (60.0, 20.0), (60.0, 0.0), (60.0, -20.0))   # (반지름 mm, 각도 deg)
PROBE_CLEARANCE_MM = 20.0
# 높이 탐지 하한 = Z0 + GRIP_DEPTH_FROM_TOP_MM + MIN_GRIP_ABOVE_Z0_MM (= 17mm, 11/18. 원본은 Z0 + 40)
#   이보다 낮은 윗면은 집을 수 없으므로 '높이 없음'
PROBE_CONTACT_N = 8.0        # 기준 대비 Fz 증가량
PROBE_FORCE_TARGET_N = 25.0
PROBE_SAFETY_N = 50.0

# 집기 접근 Force · 접촉 조건
